/* First-run installer and owner-friendly navigation. Browser-local simulation only. */
const installDefault=()=>({status:'installed',healthy:true,signedIn:true,stage:0,checks:false,dbTest:false,schema:false,owner:false,completed:[],config:{}});
let installState={...installDefault(),...(data.firstRun||{})};
setupStep=installState.venueStep||0;
let installError='';
const persistInstall=()=>{installState.venueStep=setupStep;data.firstRun=installState;save()};
const technicalNames=['Welcome','Server requirements','Database connection','Create database tables','Owner account','Venue configuration','Finish'];
const requirements=[['PHP runtime','Matches the application’s supported PHP version'],['PHP extensions','PDO PostgreSQL, mbstring, OpenSSL, cURL, DOM, XML, fileinfo, intl and required extensions'],['Application dependencies','Composer dependencies and compiled frontend assets'],['Storage & configuration','Private configuration and required storage/cache paths writable'],['Web server & HTTPS','Document root, URL rewriting, application URL and HTTPS policy'],['Background services','Scheduler, queue worker and mail configuration readiness']];
function resetInstall(status='fresh',signedIn=false,healthy=true){installState={...installDefault(),status,signedIn,healthy};setupStep=0;installError='';persistInstall()}
// A missing connection is never proof that the application is uninstalled.
function resolveEntry(m,p){
 if(m==='install'&&p==='demo')return [m,p];
 if(m==='central')return [m,p];
 if(installState.status==='installed'){
   if(!installState.healthy)return ['install','maintenance'];
   if(m==='install'||(m==='venue'&&p==='setup'))return ['venue',installState.signedIn?'dashboard':'login'];
   if(m==='venue'&&!installState.signedIn&&p!=='login')return ['venue','login'];
   if(m==='venue'&&p==='login'&&installState.signedIn)return ['venue','dashboard'];
   return [m,p];
 }
 return ['install','start'];
}
function installerGo(m,p){location.hash=m+'/'+p;readRoute()}
readRoute=function(){let [m,p]=(location.hash.replace(/^#/,'')||'venue/dashboard').split('/');m=['venue','central','public','install'].includes(m)?m:'venue';p=p||(m==='public'?'home':m==='install'?'start':'dashboard');[mode,page]=resolveEntry(m,p);if(mode!==m||page!==p)location.hash=mode+'/'+page;tab=0;sideOpen=false;publicMenu=false;render();window.scrollTo(0,0)};
const baseSwitch=switchbar;
switchbar=function(){return baseSwitch().replace('<span>No live operations</span>',`<button class="demo-installer-link" data-route="install/demo">${ic('settings')} Installer demo</button>`)};
const ownerGroups=[['Daily work',[['dashboard','Home','home'],['calendar','Calendar','calendar'],['newBooking','New booking','plus'],['reservations','Bookings','book'],['enquiries','Customer enquiries','message'],['finance','Payments & invoices','wallet'],['inventory','Inventory','box'],['approvals','Approvals','shield']]],['More booking tools',[['search','Find a record','search'],['proposals','Booking proposals','book'],['publicBookings','Online bookings','globe'],['planning','Event planning','check'],['events','Event check-in & closeout','clock'],['historical','Past invoices','book']]],['Manage your business',[['staff','Staff & permissions','users'],['programs','Hall programs','calendar'],['pricing','Packages & pricing','wallet'],['photos','Hall photos','image'],['website','Website editor','globe']]],['Settings & support',[['licensing','License & subscription','key'],['installation','System health','check'],['support','Help & support','message'],['audit','Activity & audit','audit']]]];
navVenue.splice(0,navVenue.length,...ownerGroups);
const baseNav=nav;
nav=function(groups){if(mode!=='venue')return baseNav(groups);return groups.map(([name,items],i)=>{const links=items.map(([p,label,icon])=>`<button class="nav-link ${page===p?'active':''}" data-route="venue/${p}">${ic(icon)}${esc(label)}</button>`).join('');return i===0?`<div class="nav-group">${name}</div>${links}`:`<details class="owner-nav-section" ${items.some(x=>x[0]===page)?'open':''}><summary>${esc(name)}<span>›</span></summary>${links}</details>`}).join('')+`<div class="owner-nav-footer">${btn('Sign out','owner-signout','outline sm','key')}</div>`};
const baseDashboard=dashboard;
dashboard=function(){if(mode!=='venue')return baseDashboard();let html=baseDashboard();const tasks=`<section class="owner-welcome"><div class="owner-welcome-copy"><div class="eyebrow">YOUR WORKSPACE</div><h2>Welcome back, Owner.</h2><p>What would you like to do today?</p></div><div class="owner-task-grid">${[['Add a booking','Check a date & reserve','newBooking','plus'],['Receive payment','Find an invoice or receipt','finance','wallet'],['Check availability','See open dates and halls','calendar','calendar'],['Review requests','Approve or reject requests','approvals','shield']].map(([l,d,p,i])=>`<button class="owner-task" data-route="venue/${p}"><div class="task-icon">${ic(i)}</div><div><b>${l}</b><small>${d}</small></div><span>›</span></button>`).join('')}</div></section>`;return html.replace('</header>','</header>'+tasks)};
function installerLayout(title,description,body,extra=''){
 return switchbar()+`<main class="installer-frame"><header class="installer-brand"><div class="installer-logo">✦</div><div><b>VenueDesk</b><small>by HAFZATECH</small></div><span class="installer-tag">First-time installation</span></header><div class="installer-heading"><div class="eyebrow">INSTALLATION & CONFIGURATION</div><h1>${title}</h1><p>${description}</p></div>${body}${extra}<footer class="installer-footer">VenueDesk · HAFZATECH <span>Interactive design prototype · No real server changes</span></footer></main>`;
}
function installerDemo(){return installerLayout('Preview the installation experience','Choose a sample system state. This preview control is outside the real application and never belongs in the owner menu.',`<div class="scenario-grid">${[
 ['New server','Start from scratch. Check requirements, create the database schema and configure the venue.','fresh','plus'],['Installed and signed out','Open the installer URL and see the automatic redirect to secure login.','signedout','key'],['Installed and signed in','Open the installer URL and see the automatic redirect to the owner home page.','signedin','home'],['Installed, database unavailable','Show a safe maintenance screen. Installation remains locked.','unhealthy','shield']
 ].map(([t,d,s,i])=>`<section class="card scenario"><div class="task-icon">${ic(i)}</div><h2>${t}</h2><p>${d}</p>${btn('Try this scenario','install-scenario:'+s,'primary')}</section>`).join('')}</div>`)}
function maintenance(){return installerLayout('Temporarily unavailable','The application has already been installed, but its health checks did not pass.',`<section class="card maintenance"><div class="task-icon">${ic('shield')}</div><h2>Installation is locked</h2><p>The database or application configuration cannot be verified. Your existing records must be preserved. Contact your system administrator to restore connectivity and retry the checks.</p><div class="note">No database schema will be created or reset. No login access is granted until health verification succeeds.</div><div class="actions">${btn('Retry health check','install-retry','primary')}${btn('Simulate restored connection','install-restore','outline')}</div></section>`)}
function techFields(){let s=installState.stage,c=installState.config;switch(s){case 0:return `<div class="install-intro"><div class="task-icon">${ic('settings')}</div><h2>Welcome to VenueDesk</h2><p>Install the venue management panel and its public website on your server. We’ll guide you through each step.</p></div><div class="install-checklist"><div>✓ Check software and hosting requirements</div><div>✓ Connect to an empty PostgreSQL database</div><div>✓ Create the panel and website schema</div><div>✓ Set up your owner account, halls and license</div></div><div class="note">In the real application this page is accessible only to the deployment operator using the protected first-run setup mechanism. This prototype accepts sample values only.</div>`;
case 1:return `<p class="muted" style="margin-bottom:12px">Run these checks against the actual hosting environment before proceeding. The demo uses simulated results; PHP version and extensions must be derived from the release requirements.</p><div class="check-list">${requirements.map(([n,d],i)=>`<div class="check-row"><div><b>${n}</b><small>${d}</small></div>${badge(installState.checks?(installState.requirementsOk?'Passed':i===0?'Failed':'Passed'):'Pending')}</div>`).join('')}</div><label class="field" style="margin-top:16px">Demo server status<select name="requirementsScenario"><option>All requirements available</option><option ${installState.checks&&!installState.requirementsOk?'selected':''}>Required PHP version missing</option></select></label><div class="actions" style="margin-top:14px">${btn('Run requirements check','install-check','outline','check')}</div>`;
case 2:return `<p class="muted" style="margin-bottom:16px">Use a new, dedicated PostgreSQL database. Test connection, supported server version, schema state and required privileges before installing.</p><div class="fields">${field('Database engine','engine','select','PostgreSQL',['PostgreSQL'])}${field('Database host','host','text',c.host||'127.0.0.1')}${field('Port','port','number',c.port||5432)}${field('Database name','database','text',c.database||'venuedesk_demo')}${field('Database user','dbuser','text',c.dbuser||'venuedesk_demo')}${field('Demo database password','dbpass','password','demo-only')}${field('Database scenario','dbscenario','select',c.dbscenario||'Empty database',['Empty database','Connection failed','Existing VenueDesk installation','Non-empty unrelated database'],true)}</div><div class="actions" style="margin-top:16px">${btn('Test database connection','install-dbtest','outline','check')}${installState.dbTest?badge('Connection verified'):badge('Pending')}</div><div class="note">Passwords are never retained by this prototype. Real installation must store secrets securely outside web access and must not overwrite existing tables.</div>`;
case 3:return `<div class="summary-lines"><div><span>Database connection</span>${badge(installState.dbTest?'Verified':'Pending')}</div><div><span>Database</span><b>${esc(c.database||'venuedesk_demo')}</b></div><div><span>Panel schema & migrations</span>${badge(installState.schema?'Complete':'Pending')}</div><div><span>Public website schema & defaults</span>${badge(installState.schema?'Complete':'Pending')}</div><div><span>Security configuration & application key</span>${badge(installState.schema?'Complete':'Pending')}</div></div><div class="note">A real installer runs trusted, versioned migrations against the verified database. No manual SQL, destructive reset or duplicate initialization is allowed.</div>${btn(installState.schema?'Verify schema again':'Create schema and initialize','install-schema','primary','check')}`;
case 4:return `<p class="muted" style="margin-bottom:14px">Create the first owner account. Use a one-time bootstrap link and enroll MFA before granting access.</p><div class="fields">${field('Owner name','ownerName','text',c.ownerName||'Venue Owner')}${field('Owner email','ownerEmail','email',c.ownerEmail||'owner@example.test')}${field('Demo password','ownerPassword','password','Demo-only-password')}${field('Confirm demo password','ownerConfirm','password','Demo-only-password')}${field('Demo one-time code','ownerOtp','text','123456')}</div><div class="note">Simulated owner enrollment. No password or security secret is stored by this prototype.</div>`;
case 5:return '';case 6:return `<div class="install-intro"><div class="task-icon">${ic('check')}</div><h2>Ready to finish</h2><p>Verify all installation requirements and mark this server as installed.</p></div><div class="check-list">${[['Server requirements',installState.requirementsOk],['Database connection',installState.dbTest],['Schema and website tables',installState.schema],['Owner and MFA enrollment',installState.owner],['Venue, license and operational readiness',installState.completed.length===10]].map(([n,ok])=>`<div class="check-row"><b>${n}</b>${badge(ok?'Complete':'Pending')}</div>`).join('')}</div><div class="note">After successful installation the setup route is permanently locked, removed from navigation, and redirected to the login page or owner dashboard.</div>`;
default:return ''}}
function installWizard(){let s=installState.stage;let progress= s===5?Math.round((5+setupStep/10)/7*100):Math.round(s/7*100);let savedFields=setupFields[setupStep].map((f,i)=>({...f,value:installState.config['venue'+setupStep]?.['v'+i]??f.value}));let body=s===5?`<div class="steps">${setupNames.map((n,i)=>`<button class="step ${i===setupStep?'active':installState.completed.includes(i)?'done':''}" data-install-venue-step="${i}" ${i>setupStep&&!installState.completed.includes(i)?'disabled':''}><span class="num">${installState.completed.includes(i)?'✓':i+1}</span>${esc(n)}</button>`).join('')}</div><h2>${setupStep+1}. ${setupNames[setupStep]}</h2><p class="muted" style="margin:8px 0 16px">Configure the venue before the first sign-in.</p><form id="install-venue-form">${setupStep===9?`<div class="summary-lines">${setupNames.slice(0,9).map((n,i)=>`<div><span>${n}</span>${badge(installState.completed.includes(i)?'Complete':'Pending')}</div>`).join('')}</div><div class="note">License verification is a simulated signed synthetic grant. A real installer must verify the Central-issued grant, domain and entitlements.</div>`:formFields(savedFields)}<div class="formfoot">${btn('Back','install-venue-back','outline')}<button type="submit" class="btn gold">${setupStep===9?'Verify venue readiness':'Save & continue'}</button></div></form>`:`<h2>${technicalNames[s]}</h2><form id="install-tech-form" style="margin-top:14px">${techFields()}<div class="formfoot">${s>0?btn('Back','install-back','outline'):'<span></span>'}<button type="submit" class="btn gold">${s===6?'Finish installation':s===0?'Start installation':'Continue →'}</button></div></form>`;
 return installerLayout('Install VenueDesk','One-time setup for your venue management system and public website.',`<div class="install-flow"><aside class="card install-steps"><div class="eyebrow">SETUP PROGRESS</div><div class="progress"><div style="width:${progress}%"></div></div>${technicalNames.map((n,i)=>`<div class="install-step ${i===s?'active':i<s?'done':''}"><span>${i<s?'✓':i+1}</span><div>${n}<small>${i<s?'Completed':i===s?'Current step':'Not started'}</small></div></div>`).join('')}</aside><section class="card install-body">${installError?`<div role="alert" class="install-error">${esc(installError)}</div>`:''}${body}</section></div>`)}
const baseRender=render;
render=function(){if(mode==='install'){$('#app').innerHTML=page==='demo'?installerDemo():page==='maintenance'?maintenance():installWizard();return}if(mode==='venue'&&page==='login'){$('#app').innerHTML=switchbar()+login();return}baseRender()};
const baseAction=action;
function installFail(msg){installError=msg;render()}
function installUpdate(){installError='';persistInstall();render()}
function readFields(){const fm=$('#install-tech-form');return fm?Object.fromEntries(new FormData(fm)):{};}
function checkDatabase(fd){let c=installState.config;for(const k of ['host','port','database','dbuser','dbscenario'])c[k]=fd[k]||'';installState.dbTest=false;installState.schema=false;if(fd.dbscenario==='Existing VenueDesk installation'){installState.status='installed';installState.signedIn=false;installState.healthy=true;persistInstall();installerGo('venue','login');return}if(fd.dbscenario!=='Empty database'||!fd.host||!fd.database||!fd.dbuser||!fd.dbpass||!(Number(fd.port)>0&&Number(fd.port)<=65535)){persistInstall();installFail(fd.dbscenario==='Non-empty unrelated database'?'Database is not empty. Choose a dedicated empty database.':'Connection or privileges failed. Verify the database configuration.');return}installState.dbTest=true;installUpdate()}
action=function(s){let [a,v]=s.split(':');if(a==='install-scenario'){if(v==='fresh')resetInstall('fresh');else resetInstall('installed',v==='signedin',v!=='unhealthy');installerGo('install','start');return}if(a==='owner-signout'){installState.signedIn=false;persistInstall();installerGo('venue','login');return}if(a==='install-retry'){installFail('Database connection still unavailable. Installation remains locked.');toast('Health check failed. Contact the administrator.');return}if(a==='install-restore'){installState.healthy=true;persistInstall();installerGo('install','start');return}if(a==='install-check'){let fd=readFields();installState.checks=true;installState.requirementsOk=fd.requirementsScenario==='All requirements available';persistInstall();installState.requirementsOk?installUpdate():installFail('A required PHP version is missing. Correct the server configuration and run the check again.');return}if(a==='install-dbtest'){checkDatabase(readFields());return}if(a==='install-schema'){if(!installState.dbTest){installFail('Verify the database connection first.');return}installState.schema=true;installUpdate();return}if(a==='install-back'){installState.stage=Math.max(0,installState.stage-1);installUpdate();return}if(a==='install-venue-back'){if(setupStep===0)installState.stage=4;else setupStep--;installUpdate();return}baseAction(s)};
function advanceTech(fd){let s=installState.stage;if(s===1&&(!installState.checks||!installState.requirementsOk))return installFail('All required server checks must pass before continuing.');if(s===2&&(!installState.dbTest||['host','port','database','dbuser','dbscenario'].some(k=>String(fd[k])!==String(installState.config[k]))))return installFail('Test the current database settings before continuing.');if(s===3&&!installState.schema)return installFail('Create and verify the database schema before continuing.');if(s===4){if(!fd.ownerName||!fd.ownerEmail||fd.ownerPassword!==fd.ownerConfirm||fd.ownerPassword?.length<12||fd.ownerOtp!=='123456')return installFail('Complete the owner details, matching demo password and one-time code.');installState.owner=true;installState.config.ownerName=fd.ownerName;installState.config.ownerEmail=fd.ownerEmail}if(s===6){if(!installState.requirementsOk||!installState.dbTest||!installState.schema||!installState.owner||installState.completed.length!==10)return installFail('Installation readiness checks must all pass.');installState.status='installed';installState.healthy=true;installState.signedIn=false;persistInstall();installerGo('venue','login');return}installState.stage++;installUpdate()}
function advanceVenue(fd){if(setupStep===8&&fd.v2!=='Licensed')return installFail('A valid, verified license is required before completing setup.');if(setupStep===9&&setupNames.slice(0,9).some((_,i)=>!installState.completed.includes(i)))return installFail('Complete all venue configuration steps.');installState.config['venue'+setupStep]=fd;if(!installState.completed.includes(setupStep))installState.completed.push(setupStep);if(setupStep===9)installState.stage=6;else setupStep++;installUpdate()}
document.addEventListener('click',e=>{let b=e.target.closest('[data-install-venue-step]');if(!b)return;e.preventDefault();let n=Number(b.dataset.installVenueStep);if(n<=setupStep||installState.completed.includes(n)){setupStep=n;installUpdate()}},true);
document.addEventListener('input',e=>{if(mode!=='install'||page!=='start')return;if(installState.stage===1&&e.target.name==='requirementsScenario'){installState.checks=false;installState.requirementsOk=false;persistInstall()}if(installState.stage===2&&['host','port','database','dbuser','dbpass','dbscenario'].includes(e.target.name)){installState.dbTest=false;installState.schema=false;persistInstall()}},true);
document.addEventListener('submit',e=>{let id=e.target.id;if(!['install-tech-form','install-venue-form'].includes(id)&&!(id==='demo-login'&&mode==='venue'))return;e.preventDefault();e.stopImmediatePropagation();let fd=Object.fromEntries(new FormData(e.target));if(id==='install-tech-form')advanceTech(fd);else if(id==='install-venue-form')advanceVenue(fd);else{if(installState.status!=='installed'||!installState.healthy)return;installState.signedIn=true;persistInstall();installerGo('venue','dashboard')}},true);
window.addEventListener('hashchange',readRoute);readRoute();
